import{describe,it,expect}from"vitest";import{stateProfiles,getStateProfile,getGridDimension,generatePuzzlePieces,shufflePieces,isPlacementCorrect,isPuzzleComplete,calculateCompletionPercentage}from"../../frontend/state-jigsaw/state-jigsaw.js";const REQUIRED_PROFILE_FIELDS=["id","code","name","capital","rivers","landmarks","funFacts","motto","colorTheme","patternIcon"];describe("State Jigsaw Dataset Integrity",()=>{it("contains at least 10 state puzzle profiles",()=>{expect(stateProfiles.length).toBeGreaterThanOrEqual(10)}),it("every state profile contains all required fields with non-empty values",()=>{stateProfiles.forEach((e,t)=>{REQUIRED_PROFILE_FIELDS.forEach(c=>{expect(e,`Profile at index ${t} missing field ${c}`).toHaveProperty(c),"rivers"===c||"landmarks"===c?(expect(Array.isArray(e[c])).toBe(!0),expect(e[c].length).toBeGreaterThan(0)):(expect(typeof e[c]).toBe("string"),expect(e[c].trim().length).toBeGreaterThan(0))})})}),it("all state codes and IDs are unique",()=>{const e=stateProfiles.map(e=>e.code),t=new Set(e);expect(t.size).toBe(e.length)}),it("finds state profile by code correctly",()=>{const e=getStateProfile("KL");expect(e).toBeDefined(),expect(e.name).toBe("Kerala"),expect(e.capital).toBe("Thiruvananthapuram")})}),describe("Grid Math & Piece Generation",()=>{it("calculates grid dimensions for 9, 16, and 25 pieces correctly",()=>{expect(getGridDimension(9)).toBe(3),expect(getGridDimension(16)).toBe(4),expect(getGridDimension(25)).toBe(5),expect(getGridDimension(void 0)).toBe(3)}),it("generates exact piece count with correctIndex mapping",()=>{const e=generatePuzzlePieces("KL",9);expect(e.length).toBe(9),e.forEach((e,t)=>{expect(e.correctIndex).toBe(t),expect(e.stateCode).toBe("KL"),expect(e.row).toBe(Math.floor(t/3)),expect(e.col).toBe(t%3)});const t=generatePuzzlePieces("WB",16);expect(t.length).toBe(16)}),it("shuffles pieces array",()=>{const e=generatePuzzlePieces("MH",9),t=shufflePieces(e);expect(t.length).toBe(9),expect(t).not.toBe(e)})}),describe("Placement & Completion Mechanics",()=>{it("validates placement correctness",()=>{const e={correctIndex:4};expect(isPlacementCorrect(e,4)).toBe(!0),expect(isPlacementCorrect(e,2)).toBe(!1),expect(isPlacementCorrect(null,4)).toBe(!1)}),it("detects incomplete and complete puzzle board state",()=>{const e=new Array(9).fill(null);expect(isPuzzleComplete(e,9)).toBe(!1);const t=generatePuzzlePieces("KL",9);expect(isPuzzleComplete(t,9)).toBe(!0)}),it("calculates completion percentage correctly",()=>{const e=new Array(10).fill(null);expect(calculateCompletionPercentage(e,10)).toBe(0);const t=generatePuzzlePieces("KL",9);expect(calculateCompletionPercentage(t,9)).toBe(100)})});